<?php
namespace Tests\Feature;
use App\Models\{CitySeoPage,Restaurant,Setting};use App\Services\CitySeoService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class CitySeoPagesTest extends TestCase {use RefreshDatabase;private function city(string $name,int $count):void{foreach(range(1,$count)as$i)Restaurant::create(['legacy_wp_id'=>10000+Restaurant::count(),'name'=>"$name $i",'slug'=>strtolower(str_replace(' ','-',$name))."-$i-".Restaurant::count(),'status'=>'published','city_name'=>$name]);}public function test_threshold_and_overrides_control_robots_and_sitemap():void{Setting::create(['key'=>'city_seo_minimum_restaurants','value'=>['value'=>5],'group'=>'seo']);$this->city('Grande Ville',5);$this->city('Petite Ville',2);app(CitySeoService::class)->forget();$this->get('/restos/grande-ville')->assertOk()->assertSee('index,follow',false);$this->get('/restos/petite-ville')->assertOk()->assertSee('noindex,follow',false);CitySeoPage::create(['city_name'=>'Petite Ville','state'=>'forced_open','h1'=>'H1 petit','seo_title'=>'Titre petit','seo_description'=>'Description petit','content_top'=>'<p>Haut</p>','content_bottom'=>'<p>Bas</p>']);CitySeoPage::create(['city_name'=>'Grande Ville','state'=>'forced_closed']);app(CitySeoService::class)->forget();$this->get('/restos/petite-ville')->assertOk()->assertSee('H1 petit')->assertSee('Titre petit')->assertSee('Description petit')->assertSee('Haut')->assertSee('Bas')->assertSee('index,follow',false);$this->get('/restos/grande-ville')->assertOk()->assertSee('noindex,follow',false);$this->get('/sitemap.xml')->assertSee('/restos/petite-ville')->assertDontSee('/restos/grande-ville');}}
